import sys, os
from collections import defaultdict, deque
if os.environ['USERNAME'] == 'kissz':
	inp = open('in2.txt', 'r').readline

	def debug(*args):
		print(*args, file=sys.stderr)
else:
	inp = sys.stdin.readline

	def debug(*args):
		pass

def solve():
	(n, m) = map(int, inp().split())
	G = defaultdict(list)
	for i in range(m):
		(u, v) = map(int, inp().split())
		G[u - 1] += [v - 1]
		G[v - 1] += [u - 1]
	combs = [[-1] * n for _ in range(n)]

	def bfs(i):
		Q = deque([i])
		D = [-1] * n
		D[i] = 0
		while Q:
			node = Q.pop()
			for neighbor in G[node]:
				if D[neighbor] == -1:
					Q.appendleft(neighbor)
					D[neighbor] = D[node] + 1
		return D
	dists = [bfs(i) for i in range(n)]
	for i in range(n):
		for j in range(i + 1):
			node = j
			failed = False
			while node != i:
				c = 0
				next_node = -1
				for neighbor in G[node]:
					if dists[i][neighbor] < dists[i][node]:
						c += 1
						next_node = neighbor
				if c == 1:
					node = next_node
				else:
					failed = True
					break
			call = 1
			if failed:
				combs[i][j] = combs[j][i] = 0
			else:
				for k in range(n):
					if dists[i][k] + dists[j][k] > dists[i][j]:
						c = 0
						for l in G[k]:
							if dists[i][l] + 1 == dists[i][k] and dists[j][l] + 1 == dists[j][k]:
								c += 1
						call = call * c % 998244353
				combs[i][j] = combs[j][i] = call
	for i in range(n):
		print(*combs[i])
solve()
